CREATE TABLE sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, endpoint TEXT NOT NULL, collector_type TEXT NOT NULL, classification TEXT NOT NULL, capabilities_json TEXT NOT NULL, reliability_tier TEXT NOT NULL, poll_policy_json TEXT NOT NULL, rate_limit_json TEXT NOT NULL, auth_requirement TEXT NOT NULL, health_status TEXT NOT NULL DEFAULT 'unknown', retention_policy_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE collector_runs (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK (status IN ('running','completed','failed','interrupted')), records_collected INTEGER NOT NULL DEFAULT 0, error_code TEXT, started_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE raw_records (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, external_id TEXT, canonical_url TEXT, content_type TEXT NOT NULL, content_hash TEXT NOT NULL, title TEXT, published_at TEXT, retrieved_at TEXT NOT NULL, raw_payload_ref TEXT NOT NULL, payload_excerpt TEXT NOT NULL, expires_at TEXT NOT NULL, UNIQUE(source_id, external_id));
CREATE UNIQUE INDEX idx_raw_records_canonical_url ON raw_records(canonical_url) WHERE canonical_url IS NOT NULL;
CREATE INDEX idx_raw_records_content_hash ON raw_records(content_hash);
CREATE TABLE market_observations (id TEXT PRIMARY KEY, raw_record_id TEXT NOT NULL REFERENCES raw_records(id) ON DELETE RESTRICT, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, observation_type TEXT NOT NULL, market TEXT NOT NULL, instrument TEXT NOT NULL, entity_id TEXT, observed_at TEXT NOT NULL, schema_version TEXT NOT NULL, completeness REAL NOT NULL, stale INTEGER NOT NULL DEFAULT 0, domain_json TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX idx_market_observations_instrument_time ON market_observations(instrument, observed_at);
CREATE TABLE market_snapshots (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, instrument TEXT NOT NULL, window TEXT NOT NULL, observed_at TEXT NOT NULL, metrics_json TEXT NOT NULL, schema_version TEXT NOT NULL, UNIQUE(source_id, instrument, window, observed_at));
CREATE TABLE strategy_definitions (id TEXT NOT NULL, version TEXT NOT NULL, market TEXT NOT NULL, category TEXT NOT NULL, required_observations_json TEXT NOT NULL, rolling_windows_json TEXT NOT NULL, parameters_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, PRIMARY KEY(id, version));
CREATE TABLE strategy_runs (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL, strategy_version TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('triggered','not_triggered','rejected','failed')), direction TEXT NOT NULL, score REAL NOT NULL, reason_codes_json TEXT NOT NULL, observation_ids_json TEXT NOT NULL, parameter_snapshot_json TEXT NOT NULL, rejected_reason TEXT, created_at TEXT NOT NULL, FOREIGN KEY(strategy_id, strategy_version) REFERENCES strategy_definitions(id, version) ON DELETE RESTRICT);
CREATE TABLE research_tasks (id TEXT PRIMARY KEY, query TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending','running','completed','failed','cancelled')), discovered_urls_json TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE evidence_clusters (id TEXT PRIMARY KEY, topic_key TEXT NOT NULL, original_evidence_id TEXT REFERENCES evidence(id) ON DELETE RESTRICT, members_json TEXT NOT NULL, independent_confirmations INTEGER NOT NULL DEFAULT 0, contradiction_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE supply_chain_relations (id TEXT PRIMARY KEY, upstream_entity_id TEXT NOT NULL, downstream_entity_id TEXT NOT NULL, relation_type TEXT NOT NULL, confidence TEXT NOT NULL CHECK (confidence IN ('verified','inferred')), evidence_ids_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE wallet_watchlist (id TEXT PRIMARY KEY, chain TEXT NOT NULL, address_hash TEXT NOT NULL, label TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(chain, address_hash));
CREATE TABLE website_watches (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, url TEXT NOT NULL UNIQUE, selector TEXT, content_hash TEXT, status TEXT NOT NULL, last_checked_at TEXT, created_at TEXT NOT NULL);
ALTER TABLE signal_candidates ADD COLUMN strategy_id TEXT;
ALTER TABLE signal_candidates ADD COLUMN strategy_version TEXT;
ALTER TABLE signal_candidates ADD COLUMN parameter_snapshot_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE signal_candidates ADD COLUMN reason_codes_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE signals ADD COLUMN strategy_id TEXT;
ALTER TABLE signals ADD COLUMN strategy_version TEXT;
CREATE INDEX idx_collector_runs_source_time ON collector_runs(source_id, started_at);
CREATE INDEX idx_strategy_runs_strategy_time ON strategy_runs(strategy_id, created_at);
CREATE INDEX idx_evidence_clusters_topic ON evidence_clusters(topic_key);
